)
SELECT jsonb_build_object('format','selqiro-account-horse-read-fence-20261123-v1',
 'stage','preflight','state',state,'recognized',state IN ('before','after'),'read_only',true,
 'account_rows_read',false,'account_rows_exported',false,
 'base_fingerprint',encode(sha256(convert_to(b::text,'UTF8')),'hex'),
 'target_fingerprint',encode(sha256(convert_to(t::text,'UTF8')),'hex'),
 'fence_verified',state='after') INTO observed FROM evaluated;
 IF observed->>'state' IS DISTINCT FROM 'after' THEN
  RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCOUNT_HORSE_READ_SCHEMA_MISMATCH';
 END IF;
END;
